// AegisScan correlation engine
import { llmClassify } from './llm';

export async function correlate(findings: Finding[]) {
  const grouped = await llmClassify(findings, {
    instruction: 'cluster findings into a single attack story',
    maxClusters: 12,
  });
  return grouped.map((c) => ({
    severity: scoreCluster(c),
    evidence: c.findings,
    remediation: c.suggestion,
  }));
}

function scoreCluster(c: Cluster) {
  const base = Math.max(...c.findings.map((f) => f.cvss));
  const corroboration = new Set(c.findings.map((f) => f.tool)).size;
  return base * (1 + 0.15 * corroboration);
}

import asyncio
from agents import LogParser, Anomaly, ThreatIntel, Response, Reporter

class Orchestrator:
    def __init__(self):
        self.agents = {
            'parse':   LogParser(),
            'anomaly': Anomaly(),
            'intel':   ThreatIntel(),
            'respond': Response(),
            'report':  Reporter(),
        }

    async def analyse(self, alert):
        parsed = await self.agents['parse'].run(alert)
        intel, anomaly = await asyncio.gather(
            self.agents['intel'].run(parsed),
            self.agents['anomaly'].run(parsed),
        )
        plan = await self.agents['respond'].run(parsed, intel, anomaly)
        return await self.agents['report'].run(parsed, intel, anomaly, plan)

# CIS AWS 2.7: S3 buckets must not be publicly readable
from autonomus import rule, Severity

@rule(framework='cis-aws', id='2.7', severity=Severity.HIGH)
def s3_no_public_read(account):
    for bucket in account.s3.buckets():
        acl = bucket.acl()
        if 'AllUsers' in acl.public_grants:
            yield Violation(
                resource=bucket.arn,
                reason='AllUsers has read grant',
                auto_fix=lambda: bucket.set_block_public_access(True),
            )

import pandas as pd
from validation import gate

@gate(schema='positions_v3', rules=['no_nulls', 'sum_balance'])
def transform_positions(df: pd.DataFrame) -> pd.DataFrame:
    df = df.assign(
        traded_at=pd.to_datetime(df['traded_at'], utc=True),
        notional=df['qty'] * df['price'],
    )
    return (
        df
        .dropna(subset=['account_id', 'ticker'])
        .groupby(['account_id', 'ticker', pd.Grouper(key='traded_at', freq='D')])
        .agg(qty=('qty', 'sum'), notional=('notional', 'sum'))
        .reset_index()
    )

from llm import classify
from runbooks import LIBRARY

CONFIDENCE_THRESHOLD = 0.85

def handle_ticket(ticket):
    label, conf = classify(ticket.text, labels=LIBRARY.keys())
    if conf < CONFIDENCE_THRESHOLD:
        diagnostics = run_diagnostics_for(label, ticket)
        return escalate(ticket, label, conf, diagnostics)
    runbook = LIBRARY[label]
    result = runbook.execute(ticket)
    return close(ticket, runbook, result)

import { useHoldings, usePrices } from '@/lib/api';

export default function Portfolio() {
  const holdings = useHoldings();
  const prices = usePrices(holdings.map((h) => h.symbol));
  const totalUsd = holdings.reduce((sum, h) =>
    sum + h.qty * (prices[h.symbol] ?? 0), 0);

  return (
    <main className="min-h-screen bg-black text-white">
      <HeaderBalance value={totalUsd} delta={holdings.dayChange} />
      <HoldingsList rows={holdings} prices={prices} />
      <ProgressiveDisclosure>
        <AdvancedOrders />
        <CustodyOptions />
        <SecuritySettings />
      </ProgressiveDisclosure>
    </main>
  );
}
